sys_variable_value.value:
(function execute(inputs, outputs) {
    try {
        var ritmSysId = inputs.ritm_sys_id;

        if (sys_id) {
            successCount++;
        } else {
            errorCount++;
            gs.error('Failed to insert row ' + i + ': ' + line);
        }

        // Read the CSV attachment from the RITM
        var attachmentGR = new GlideRecord('sys_attachment');
        attachmentGR.addQuery('table_sys_id', ritmSysId);
        attachmentGR.addQuery('file_name', 'ENDSWITH', '.csv');
        attachmentGR.orderByDesc('sys_created_on');
        attachmentGR.setLimit(1);
        attachmentGR.query();

        if (!attachmentGR.next()) {
            gs.error('Bulk Workspace Import: No CSV attachment found on RITM ' + ritmSysId);
            outputs.result = 'Error: No CSV file found on the request.';
            outputs.record_count = '0';
            return;
        }

        // Read CSV content
        var attachment = new GlideSysAttachment();
        var csvContent = attachment.getContent(attachmentGR);

        if (!csvContent) {
            gs.error('Bulk Workspace Import: CSV attachment was empty');
            outputs.result = 'Error: The uploaded CSV file was empty.';
            outputs.record_count = '0';
            return;
        }

        // Split into lines, skip header
        var lines = csvContent.split('\n');
        gs.info('Bulk Workspace Import: Total lines including header: ' + lines.length);

        var successCount = 0;
        var errorCount = 0;

        // Create one Import Set record per data row
        for (var i = 1; i < lines.length; i++) {
            var line = lines[i].trim();
            if (!line) continue;

            // Handle commas inside quoted fields
            var values = line.split(',');

            // Insert into staging table via GlideRecord
            // Import set tables accept direct GlideRecord inserts
            // when the table extends sys_import_set_row
            var staging = new GlideRecord('x_1903615_worksp_0_workspace_import_stage');
            staging.initialize();
            staging.workspace_name = values[0] ? values[0].trim() : '';
            staging.workspace_type = values[1] ? values[1].trim() : '';
            staging.location = values[2] ? values[2].trim() : '';
            staging.max_occupancy = values[3] ? values[3].trim() : '0';
            staging.status = values[4] ? values[4].trim() : '';
            staging.workspace_description = values[5] ? values[5].trim() : '';
            staging.image = values[6] ? values[6].trim() : '';

            var sys_id = staging.insert();
            gs.info('Row ' + i + ' insert result: ' + sys_id);

            if (sys_id) {
                successCount++;
            } else {
                errorCount++;
                gs.error('Failed to insert row ' + i + ': ' + line);
            }
        }

        gs.info('Bulk Workspace Import: Inserted ' + successCount + ' rows into staging table');

        // Note: No explicit transform call needed.
        // The staging table has a "Transform synchronously" business rule
        // that automatically runs the "Workspace records" transform map
        // on every insert. Records flow to Workspace Options immediately.

        outputs.result = 'Import completed. ' + successCount + ' records processed, ' + errorCount + ' errors.';
        outputs.record_count = successCount + '';

    } catch (ex) {
        gs.error('Bulk Workspace Import error: ' + ex.message);
        outputs.result = 'Import failed: ' + ex.message;
        outputs.record_count = '0';
    }
})(inputs, outputs);

